def linear_search(arr, target):
    for i in range(len(arr)):
        if arr[i] == target:
            return i

    return -1

print(linear_search([3, 8, 5, 11, 2], 11))
print(linear_search([3, 8, 5, 11, 2], 10))

def count_occurrences(arr, target):
    count = 0

    for value in arr:
        if value == target:
            count += 1

    return count

print(count_occurrences([1, 2, 2, 3], 2))

def last_occurrence(arr, target):
    last_index = -1

    for i in range(len(arr)):
        if arr[i] == target:
            last_index = i

    return last_index

print(last_occurrence([1, 2, 2, 3], 2))
